// This file is generated by AI.

// 全局音频播放器: **任意时刻只有一个在响**。
//
// 用模块级单例, 不遍历 DOM 里的 `<audio>` (那样管不到卸载后残留的元素); 也刻意**不放进
// store**: 播放状态是纯粹的瞬态界面细节, 每播一次写 store 会连带触发状态栏、文件树、
// 编辑器 watcher 等无关订阅者。

/** 当前正在播放的音源 (null 表示没有)。 */
let current: HTMLAudioElement | null = null;
/** 当前音源的标识 (通常是文件路径或音频哈希), 供界面判断"是不是我在响" */
let currentKey: string | null = null;
/** 播放状态变化的通知者 */
const listeners = new Set<(key: string | null) => void>();

function notify(): void {
  for (const listener of listeners) listener(currentKey);
}

/**
 * 播放一个音源, 并停掉上一个。
 *
 * `key` 用来让界面知道"现在响的是不是我"; 传同一个 key 再调一次视为重新开始。
 * 返回一个 `stop` 函数, 便于调用方在卸载时清理。
 */
export function playAudio(source: string, key: string): () => void {
  stopAudio();
  const audio = new Audio(source);
  current = audio;
  currentKey = key;
  notify();

  // 播完自动复位, 免得界面一直显示"正在播放"
  audio.addEventListener('ended', () => {
    if (current === audio) stopAudio();
  });
  audio.addEventListener('error', () => {
    if (current === audio) stopAudio();
  });

  void audio.play().catch(() => {
    // 自动播放被拒 / 解码失败: 直接复位, 不要让界面卡在"播放中"
    if (current === audio) stopAudio();
  });

  return () => {
    if (current === audio) stopAudio();
  };
}

/** 停掉当前音源 (没有在播时是无操作)。 */
export function stopAudio(): void {
  const audio = current;
  current = null;
  currentKey = null;
  // 本来就没在播: 不通知 —— `playAudio` 会先调这里, 无条件广播会让订阅者白算一轮。
  if (!audio) return;

  audio.pause();
  // 清 src 让浏览器释放解码缓冲; 不 assign 空串是为了避免某些 WebView 触发 error 事件
  audio.removeAttribute('src');
  audio.load();
  notify();
}

/** 当前正在响的音源标识 (没有则为 null)。 */
export function playingKey(): string | null {
  return currentKey;
}

/** 切换: 同一个 key 再点一次就停。 */
export function toggleAudio(source: string, key: string): void {
  if (currentKey === key) stopAudio();
  else playAudio(source, key);
}

/**
 * 播放一个音源的**某一段** (秒), 到区间末尾自动停 —— 用于试听裁剪结果: 把整段原音频放出来
 * 就无从判断裁剪位置对不对。
 *
 * 仍走上面那套单例, "同一时刻只有一个在响"这条不变; 到点停止用定时器而不是 `timeupdate`
 * (后者在 WebView 里约 250ms 才推一次, 收尾会拖)。
 */
export function playAudioRange(source: string, key: string, start: number, end: number): () => void {
  const stop = playAudio(source, key);
  const audio = current;
  if (!audio) return stop;

  // 从区间起点开始: `currentTime` 在元数据就绪前赋值会被忽略, 因此监听一次 loadedmetadata
  const seek = () => {
    try {
      audio.currentTime = Math.max(0, start);
    } catch {
      // 少数容器在未就绪时赋值会抛, 忽略即可 —— 播放仍从 0 开始, 只是不够精确
    }
  };
  if (audio.readyState >= 1) seek();
  else audio.addEventListener('loadedmetadata', seek, { once: true });

  const span = Math.max(0, end - start);
  // 定时器只负责"停"; 它比实际播放长约 80ms, 让音频自然播完而不是被硬切
  const timer = setTimeout(
    () => {
      if (current === audio) stopAudio();
    },
    span * 1000 + 80
  );

  return () => {
    clearTimeout(timer);
    stop();
  };
}

/** 订阅"当前音源"的变化, 返回取消订阅函数。 */
export function subscribeAudio(listener: (key: string | null) => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}
